        std::lock_guard<std::mutex> fx(e->fxMutex);
        e->reverbNode.setMix(mix);
        e->reverbNode.setRoomSize(room_size);
        e->reverbNode.setDamping(damping);
        e->reverbNode.setPreDelayMs(pre_delay_ms);
        e->reverbNode.setWidth(width);
