    {
        if (engine)
        {
            const int sr = (engine->engineSampleRate > 0) ? engine->engineSampleRate : engine->sampleRate;
            engine->lookaheadLimiter.updateParams(
                sr,
                engine->channels,
                ceiling_dbtp,
                attack_ms,
                release_ms
            );
        }
    }

